<?= view('web/_layout_top', get_defined_vars()) ?>
<?php $modalToOpen = (string) (session('modal') ?: (old('_modal_context') === 'create-account' ? 'create-account-modal' : '')); ?>
<section class="card">
  <div class="cms-page-toolbar"><div><p>ACCESS MANAGEMENT</p><h2>CMS accounts</h2><span>Manage administrators, Studio operators, and film distributors.</span></div><div class="cms-toolbar-actions"><span class="count"><?= count($users) ?> accounts</span><button class="btn primary" type="button" data-cms-modal-open="create-account-modal">+ Add Account</button></div></div>
  <form method="get" action="<?= site_url('control/operators') ?>" class="filter-row account-filters"><input name="q" value="<?= esc($filters['q']) ?>" placeholder="Search name or email"><select name="role"><option value="">All roles</option><option value="admin" <?= $filters['role'] === 'admin' ? 'selected' : '' ?>>Administrator</option><option value="operator" <?= $filters['role'] === 'operator' ? 'selected' : '' ?>>Operator</option><option value="distributor" <?= $filters['role'] === 'distributor' ? 'selected' : '' ?>>Distributor</option></select><select name="status"><option value="">All statuses</option><option value="active" <?= $filters['status'] === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= $filters['status'] === 'inactive' ? 'selected' : '' ?>>Inactive</option></select><button class="btn primary" type="submit">Search</button><a class="btn ghost" href="<?= site_url('control/operators') ?>">Reset</a></form>
  <div class="account-list"><?php if ($users === []): ?><div class="empty">No accounts match the current filters.</div><?php endif ?>
  <?php foreach ($users as $user): $key = (int) $user->id; $isSelf = $key === (int) $admin->id; ?>
    <article class="account-row"><div class="account-summary"><span class="avatar"><?= esc(mb_strtoupper(mb_substr($user->name, 0, 1))) ?></span><div><strong><?= esc($user->name) ?></strong><small><?= esc($user->email) ?><?= $user->role === 'operator' ? ' · ' . ($studioCounts[$key] ?? 0) . ' Studio(s)' : '' ?></small></div><span class="badge <?= esc($user->status) ?>"><?= esc(strtoupper($user->status)) ?></span><span class="role"><?= esc($user->role) ?></span></div><div class="account-actions"><button class="btn ghost" type="button" data-cms-modal-open="edit-account-<?= $key ?>">Edit details</button><button class="btn ghost" type="button" data-cms-modal-open="password-account-<?= $key ?>">Reset password</button><button class="btn <?= $user->status === 'active' ? 'danger' : 'primary' ?>" type="button" data-cms-modal-open="status-account-<?= $key ?>" <?= $isSelf && $user->status === 'active' ? 'disabled title="You cannot deactivate your own account"' : '' ?>><?= $user->status === 'active' ? 'Deactivate' : 'Activate' ?></button></div></article>
    <dialog class="cms-action-modal" id="edit-account-<?= $key ?>" data-cms-modal <?= $modalToOpen === 'edit-account-' . $key ? 'data-auto-open="true"' : '' ?>><form method="post" action="<?= site_url('control/operators/' . $key . '/update') ?>" class="cms-modal-shell cms-modal-form"><?= csrf_field() ?><input type="hidden" name="_modal_context" value="edit-account-<?= $key ?>"><header class="cms-modal-header"><div><p>ACCOUNT DETAILS</p><h2>Edit <?= esc($user->name) ?></h2><span>Changes to roles take effect on the next authorized request.</span></div><button class="cms-modal-x" type="button" data-cms-modal-close>×</button></header><div class="cms-modal-body cms-form-grid"><label>Name<input name="name" value="<?= esc($modalToOpen === 'edit-account-' . $key ? old('name', $user->name) : $user->name) ?>" maxlength="120" required autofocus></label><label>Email<input type="email" name="email" value="<?= esc($modalToOpen === 'edit-account-' . $key ? old('email', $user->email) : $user->email) ?>" required></label><label class="wide">Role<?php $editRole = $modalToOpen === 'edit-account-' . $key ? old('role', $user->role) : $user->role; ?><select name="role"><option value="operator" <?= $editRole === 'operator' ? 'selected' : '' ?>>Operator</option><option value="distributor" <?= $editRole === 'distributor' ? 'selected' : '' ?>>Distributor</option><option value="admin" <?= $editRole === 'admin' ? 'selected' : '' ?>>Administrator</option></select></label></div><footer class="cms-modal-footer"><span><?= $isSelf ? 'This is your signed-in account.' : 'Account access settings' ?></span><div><button class="btn ghost" type="button" data-cms-modal-close>Cancel</button><button class="btn primary" type="submit">Save Details</button></div></footer></form></dialog>
    <dialog class="cms-action-modal" id="password-account-<?= $key ?>" data-cms-modal><form method="post" action="<?= site_url('control/operators/' . $key . '/password') ?>" class="cms-modal-shell cms-modal-form"><?= csrf_field() ?><header class="cms-modal-header"><div><p>SECURITY</p><h2>Reset password</h2><span>Set a new password for <?= esc($user->name) ?>.</span></div><button class="cms-modal-x" type="button" data-cms-modal-close>×</button></header><div class="cms-modal-body"><div class="cms-icon-note"><span>⌁</span><span>All active API sessions for this account will be revoked after the password changes.</span></div><label style="margin-top:15px">New password<input type="password" name="password" minlength="12" autocomplete="new-password" required autofocus></label></div><footer class="cms-modal-footer"><span>Minimum 12 characters</span><div><button class="btn ghost" type="button" data-cms-modal-close>Cancel</button><button class="btn primary" type="submit">Update Password</button></div></footer></form></dialog>
    <dialog class="cms-action-modal" id="status-account-<?= $key ?>" data-cms-modal><form method="post" action="<?= site_url('control/operators/' . $key . '/status') ?>" class="cms-modal-shell"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $user->status === 'active' ? 'inactive' : 'active' ?>"><header class="cms-modal-header"><div><p>ACCOUNT LIFECYCLE</p><h2><?= $user->status === 'active' ? 'Deactivate' : 'Activate' ?> <?= esc($user->name) ?>?</h2></div><button class="cms-modal-x" type="button" data-cms-modal-close>×</button></header><div class="cms-modal-body"><div class="cms-confirm-message <?= $user->status === 'active' ? 'danger' : '' ?>"><strong><?= $user->status === 'active' ? 'The user will lose CMS and API access.' : 'The user will regain access according to their role.' ?></strong><?= $user->status === 'active' ? 'Existing Studio assignments remain recorded, but active API sessions are revoked.' : 'They can sign in again with their existing password.' ?></div></div><footer class="cms-modal-footer"><span>Account status change</span><div><button class="btn ghost" type="button" data-cms-modal-close>Cancel</button><button class="btn <?= $user->status === 'active' ? 'danger' : 'primary' ?>" type="submit">Confirm <?= $user->status === 'active' ? 'Deactivation' : 'Activation' ?></button></div></footer></form></dialog>
  <?php endforeach ?></div>
</section>
<dialog class="cms-action-modal" id="create-account-modal" data-cms-modal <?= $modalToOpen === 'create-account-modal' ? 'data-auto-open="true"' : '' ?>><form method="post" action="<?= site_url('control/operators') ?>" class="cms-modal-shell cms-modal-form"><?= csrf_field() ?><input type="hidden" name="_modal_context" value="create-account"><header class="cms-modal-header"><div><p>NEW ACCOUNT</p><h2>Add a CMS account</h2><span>Operators control assigned Studios; distributors submit films.</span></div><button class="cms-modal-x" type="button" data-cms-modal-close>×</button></header><div class="cms-modal-body cms-form-grid"><label>Name<input name="name" value="<?= esc(old('name')) ?>" maxlength="120" required autofocus></label><label>Email<input type="email" name="email" value="<?= esc(old('email')) ?>" required></label><label>Role<select name="role"><option value="operator" <?= old('role', 'operator') === 'operator' ? 'selected' : '' ?>>Operator</option><option value="distributor" <?= old('role') === 'distributor' ? 'selected' : '' ?>>Distributor</option><option value="admin" <?= old('role') === 'admin' ? 'selected' : '' ?>>Administrator</option></select></label><label>Initial password<input type="password" name="password" minlength="12" required autocomplete="new-password"></label></div><footer class="cms-modal-footer"><span>Password must contain at least 12 characters.</span><div><button class="btn ghost" type="button" data-cms-modal-close>Cancel</button><button class="btn primary" type="submit">Create Account</button></div></footer></form></dialog>
